import numpy as np
A=np.array(g)
def comps(arr, pred):
 h,w=arr.shape; seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if pred(arr[r,c]) and (r,c) not in seen:
    st=[(r,c)];seen.add((r,c)); pts=[]
    while st:
     x,y=st.pop();pts.append((x,y))
     for q in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
      if 0<=q[0]<h and 0<=q[1]<w and q not in seen and pred(arr[q]):seen.add(q);st.append(q)
    out.append(pts)
 return out
def shp(pts):
 r0=min(r for r,c in pts);c0=min(c for r,c in pts); h=max(r for r,c in pts)-r0+1;w=max(c for r,c in pts)-c0+1
 return tuple(''.join('#' if (r+r0,c+c0) in pts else '.' for c in range(w)) for r in range(h))
maskcomps=comps(A[:,:7],lambda x:x==7)
[(len(p), (min(r for r,c in p),min(c for r,c in p)),shp(p)) for p in maskcomps]
